import math
phase='REV'
fwd_start=None
prev_alpha=0.0
lastp=-10
L1=2.75;A=1.05;L2=2.6
def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a
def clamp(x,lo,hi):
    return max(lo,min(hi,x))
def deq(th):
    r=math.radians(th)
    return math.degrees(math.atan(L1*math.sin(r)/(L2+A*math.cos(r))))
def control(obs):
    global phase,fwd_start,prev_alpha,lastp
    try:
        t=obs['t'];th=obs['hitch_deg']
        rig=obs['rig'];R=rig['trailer_rear'];bt=rig['trailer_heading_deg']+180.0
        views=obs.get('views') or {}
        if phase=='FWD':
            if t-fwd_start>2.0 and abs(th)<10:
                phase='REV'
            else:
                return (clamp(-0.6*th,-25,25),1.0,-23)
        if abs(th)>38:
            phase='FWD';fwd_start=t
            wake('hitch %.0f, pulling forward'%th)
            return (clamp(-0.6*th,-25,25),1.0,-23)
        pts=[]
        for vn,v in views.items():
            if not v: continue
            ox,oy=v['origin']
            for b,d in v.get('walls',[]):
                x=ox+d*math.cos(math.radians(b));y=oy+d*math.sin(math.radians(b))
                dx=x-R[0];dy=y-R[1]
                r=math.hypot(dx,dy)
                a=wrap(math.degrees(math.atan2(dy,dx))-bt)
                pts.append((r,a))
        hw=rig.get('trailer_half_width',0.85)+0.3
        alpha=prev_alpha
        if pts:
            cands=list(range(-70,71,5))
            frees=[]
            for c in cands:
                f=9.0
                for r,a in pts:
                    ra=math.radians(a-c)
                    u=r*math.cos(ra);w=r*math.sin(ra)
                    if u>0.3 and abs(w)<hw and u<f: f=u
                frees.append(f)
            m=max(frees)
            best=min([i for i in range(len(cands)) if frees[i]>=m-0.05],key=lambda i:abs(cands[i]-prev_alpha))
            lo=best;hi=best
            while lo>0 and frees[lo-1]>=m-0.5: lo-=1
            while hi<len(cands)-1 and frees[hi+1]>=m-0.5: hi+=1
            alpha=0.5*(cands[lo]+cands[hi])
        cam=views.get('camera') or {}
        tc=cam.get('target_corners') if cam else None
        if tc:
            ox,oy=cam['origin'];sx=sy=0;n=0
            for c in tc:
                b,d=c[0],c[1]
                sx+=ox+d*math.cos(math.radians(b));sy+=oy+d*math.sin(math.radians(b));n+=1
            cx=sx/n-R[0];cy=sy/n-R[1]
            ac=wrap(math.degrees(math.atan2(cy,cx))-bt)
            if abs(ac)<70 and math.hypot(cx,cy)>0.8: alpha=0.3*alpha+0.7*ac
        prev_alpha=0.7*prev_alpha+0.3*alpha
        rem=obs['progress']['remaining']
        if rem<2.5: thd=clamp(0.4*prev_alpha,-10,10)
        else: thd=clamp(0.8*prev_alpha,-28,28)
        st=clamp(deq(th)+1.3*(th-thd),-34,34)
        if t-lastp>2:
            lastp=t;print('t%.1f th%.1f thd%.1f a%.1f st%.1f rem%.1f np%d'%(t,th,thd,prev_alpha,st,rem,len(pts)))
        return (st,-0.8,-23)
    except Exception as e:
        print('err',e)
        return (0,-0.5,-23)

