        elif rem<2.5: thd=clamp(-0.4*prev_alpha,-10,10)
        else: thd=clamp(-0.8*prev_alpha,-22,22)
        st=clamp(deq(th)+1.3*(th-thd),-34,34)
        if dist<1.0: st=clamp(st,-6,3)
        if fr: st=min(st,0.0)
        if fl: st=max(st,0.0)
        if t-lastp>2:
            lastp=t;print('t%.1f th%.1f thd%.1f a%.1f st%.1f rem%.1f d%.1f fr%d fl%d'%(t,th,thd,prev_alpha,st,rem,dist,fr,fl))
        return (st,-0.7,-23)
    except Exception as e:
        print('err',e)
        return (0,-0.5,-23)

