import math
X=0.0;Y=0.0;TH=0.0
cells={}
phase='fwd'
fwd_mode='S'
gi=0;gt=0.0
last_touch=None
fwd_dist=0.0
lastprint=-10
hdf=None
hdes_prev=0.0
CS=0.25
GAZE=[(140,0.5),(64,0.6),(-64,0.6),(-140,0.5),(-64,0.6),(64,0.6)]

def w(lx,ly):
    c=math.cos(TH); s=math.sin(TH)
    return X+c*lx-s*ly, Y+s*lx+c*ly

def tol(wx,wy):
    c=math.cos(TH); s=math.sin(TH)
    dx=wx-X; dy=wy-Y
    return c*dx+s*dy, -s*dx+c*dy

def mind(lx,ly):
    wx,wy=w(lx,ly)
    m=99.0
    for px,py,_ in cells.values():
        d=(px-wx)**2+(py-wy)**2
        if d<m: m=d
    return math.sqrt(m)

def chain(seeds,allowed):
    seen=set(seeds)
    st=list(seeds)
    while st:
        kx,ky=st.pop()
        for ddx in range(-3,4):
            for ddy in range(-3,4):
                n=(kx+ddx,ky+ddy)
                if n in allowed and n not in seen:
                    seen.add(n); st.append(n)
    return seen

def control(obs):
    global X,Y,TH,phase,gi,gt,last_touch,fwd_dist,lastprint,fwd_mode,hdf,hdes_prev
    dt=obs.get('dt',0.1) or 0.1
    t=obs['t']
    v=obs['motion']['v_mps']
    st=math.radians(obs['steer_deg'])
    TH+=v*math.tan(st)/2.5*dt
    X+=v*math.cos(TH)*dt; Y+=v*math.sin(TH)*dt
    c=math.cos(TH); s=math.sin(TH)
    views=obs.get('views') or {}
    for name,vw in views.items():
        try:
            ox,oy=vw['origin']
            for p in vw.get('walls',[]):
                b,d=p[0],p[1]
                if d>14: continue
                if name=='right_mirror' and d>9: continue
                br=math.radians(b)
                lx=ox+d*math.cos(br); ly=oy+d*math.sin(br)
                wx=X+c*lx-s*ly; wy=Y+s*lx+c*ly
                cells[(round(wx/CS),round(wy/CS))]=(wx,wy,t)
        except Exception:
            pass
    for k in list(cells.keys()):
        if t-cells[k][2]>25: del cells[k]
    hd=obs['head']
    g,hold=GAZE[gi]
    if abs(hd['gaze_deg']-g)<2 and hd.get('settled',True):
        gt+=dt
        if gt>=hold:
            gi=(gi+1)%len(GAZE); gt=0.0
    look=GAZE[gi][0]
    h=obs['hitch_deg']
    status=obs['status']
    rig=obs['rig']
    try:
        fx=float(rig.get('vehicle_front',3.15))
    except Exception:
        try: fx=float(rig['vehicle_front'][0])
        except Exception: fx=3.15
    vhw=rig.get('vehicle_half_width',1.15) or 1.15
    touches=obs['counters']['touches']
    if last_touch is None: last_touch=touches
    if touches>last_touch:
        last_touch=touches
        fwd_dist=0.0
        rx,ry=rig['trailer_rear']; tht=math.radians(rig['trailer_heading_deg']); thw=rig.get('trailer_half_width',1.2)
        dFR=mind(fx,-vhw); dFL=mind(fx,vhw)
        dT=min(mind(rx-thw*math.sin(tht),ry+thw*math.cos(tht)),mind(rx+thw*math.sin(tht),ry-thw*math.cos(tht)))
        m=min(dFR,dFL,dT)
        fwd_mode='FR' if m==dFR else ('FL' if m==dFL else 'S')
        phase='fwd'
        print('touch',fwd_mode,round(dFR,2),round(dFL,2),round(dT,2))
    if status=='JACKKNIFED' or abs(h)>50:
        if phase!='fwd' or fwd_mode!='J': fwd_dist=0.0
        phase='fwd'; fwd_mode='J'
    if phase=='fwd':
        fwd_dist+=max(v,0)*dt
        if fwd_mode=='FR':
            steer=25.0; done=fwd_dist>2.0 and abs(h)<45
        elif fwd_mode=='FL':
            steer=-25.0; done=fwd_dist>2.0 and abs(h)<45
        elif fwd_mode=='S':
            steer=0.0; done=fwd_dist>2.5
        else:
            steer=max(-35,min(35,-1.5*h)); done=fwd_dist>1.5 and abs(h)<20
        if done:
            phase='rev'; hdf=None
        else:
            return (steer,0.7,look)
    rx,ry=rig['trailer_rear']
    Rx,Ry=w(rx,ry)
    allowed=set()
    lseeds=[];rseeds=[]
    for k,(px,py,_) in cells.items():
        if (px-Rx)**2+(py-Ry)**2>121 and (px-X)**2+(py-Y)**2>36: continue
        allowed.add(k)
        lx,ly=tol(px,py)
        if -2.5<lx<3.5:
            if ly<-1.4: rseeds.append(k)
            elif ly>1.4: lseeds.append(k)
    rs=set(rseeds)
    Lset=chain(lseeds,allowed-rs)
    Rset=chain(rseeds,allowed-Lset)
    psib=TH+math.radians(180-h)
    ux=math.cos(psib); uy=math.sin(psib)
    Lb=None;Rb=None;Ln=None;Rn=None;Lf=None;Rf=None
    for k in Lset:
        px,py,_=cells[k]; dx=px-Rx; dy=py-Ry
        a=dx*ux+dy*uy; l=dx*uy-dy*ux
        if 1.5<=a<=4.5: Lb=l if Lb is None else min(Lb,l)
        if -0.5<=a<1.5: Ln=l if Ln is None else min(Ln,l)
        if 3.0<=a<=6.5: Lf=l if Lf is None else min(Lf,l)
    for k in Rset:
        px,py,_=cells[k]; dx=px-Rx; dy=py-Ry
        a=dx*ux+dy*uy; l=dx*uy-dy*ux
        if 1.5<=a<=4.5: Rb=l if Rb is None else max(Rb,l)
        if -0.5<=a<1.5: Rn=l if Rn is None else max(Rn,l)
        if 3.0<=a<=6.5: Rf=l if Rf is None else max(Rf,l)
    A=3.0
    T=None
    if Lb is not None and Rb is not None:
        cc=0.5*(Lb+Rb)
        if Lf is not None and Rf is not None: cf=0.5*(Lf+Rf)
        elif Lf is not None: cf=Lf-2.8
        elif Rf is not None: cf=Rf+2.8
        else: cf=cc
        ac=math.degrees(math.atan2(cf,4.75))
        if ac>8: T=max(cc,Lb-2.0)
        elif ac<-8: T=min(cc,Rb+2.0)
        else: T=cc
    elif Lb is not None: T=Lb-2.2
